\u003d\u004e\u006c\u0024\u0070\u0049\u0079\u003f\u0059\u002f\u0030\u0039\u0021\u0048\u0052\u0061\u007b\u0049\u002b\u007d\u005a\u0058\u0053\u0067\u002a\u0041\u006b\u005a\u006e\u0076\u007a\u0023\u0045\u0046\u0034\u003f\u0058\u0070\u007b\u003b\u0023\u0022\u0066\u0047\u007e\u0068\u003b\u0028\u0047\u0042\u0049\u0039\u003f\u003e\u0023\u0024\u0073\u0068\u006d\u0059\u005b\u0067\u006c\u0026\u0066\u006c\u003d\u0064\u0048\u0058\u006b\u0062\u007c\u0063\u003e\u0048\u003f\u0021\u0033\u005f\u003f\u0064\u0048\u0058\u0039\u007c\u0038\u004a\u003c\u0028\u006d\u007e\u0033\u004b\u004c\u0045\u007e\u007d\u0065\u002b\u0024\u007c\u0021\u0037\u0033\u0068\u0043\u0046\u0059\u0046\u0036\u006b\u0066\u0053\u005f\u006c\u007a\u0077\u004b\u005d\u006c\u0056\u002c\u002e\u0055\u0077\u0048\u0072\u0047\u0073\u0060\u006d\u007b\u0056\u0073\u0057\u0023\u004f\u004c\u0056\u0044\u0031\u0071\u0031\u0066\u0049\u0051\u004b\u004c\u0021\u006b\u0024\u0034\u0076\u0045\u004b\u0059\u0058\u0064\u0068\u006f\u007d\u002b\u0028\u0053\u003c\u0057\u007b\u0066\u0077\u004b\u0057\u0023\u0043\u0043\u005a\u0065\u0066\u0044\u0051\u0025\u0072\u0048\u0042\u0049\u0021\u0038\u0072\u007a\u0058\u0072\u006e\u0037\u0048\u006c\u002c\u006c\u003b\u007c\u003f\u004a\u0029\u003f\u0056\u0061\u0048\u0038\u0046\u0023\u0032\u0040\u0062\u003d\u0058\u0056\u0044\u002e\u0035\u0070\u0039\u0053\u006b\u0034\u007a\u0036\u007d\u007c\u0077\u0021\u004b\u004c\u0048\u003a\u003c\u0051\u006d\u0034\u005a\u0059\u004b\u005f\u0056\u002c\u0045\u003f\u0041\u003a\u0066\u003a\u0072\u004f\u006f\u005d\u0065\u004c\u002b\u0061\u006f\u002f\u004b\u005e\u006a\u0049\u0042\u003b\u006a\u0057\u003c\u0073\u0025\u003e\u0056\u003d\u0074\u0039\u0069\u0032\u0039\u0049\u002a\u003c\u0068\u0049\u006b\u0069\u0067\u0031\u0069\u0049\u0071\u0039\u0039\u0059\u0036\u0021\u003a\u004c\u0040\u003c\u0067\u0031\u0069\u0049\u0071\u0039\u003b\u0035\u006b\u0021\u0072\u0070\u005f\u002a\u006d\u0058\u0052\u0065\u0059\u004f\u007b\u0032\u0021\u0042\u0075\u0029\u002a\u006d\u0058\u0052\u0065\u0059\u0025\u0042\u0029\u0068\u0033\u0039\u0060\u005d\u0037\u0039\u007d\u003a\u007a\u0071\u004e\u003c\u0074\u0075\u005a\u0032\u0075\u0079\u0079\u0035\u0075\u004c\u004f\u0067\u0054\u007b\u007a\u0065\u004a\u0055\u004b\u004e\u0023\u0038\u0036\u004f\u005e\u0026\u0052\u0031\u0076\u005e\u0050\u0042\u0062\u0035\u002b\u0030\u005d\u006d\u005f\u0052\u003a\u007c\u0024\u0069\u0052\u0032\u003c\u0034\u0021\u006c\u005d\u0024\u0069\u0077\u002f\u0066\u0074\u002b\u0032\u003f\u0057\u003e\u0022\u005d\u0021\u0035\u006d\u0065\u003c\u0051\u0056\u0029\u0038\u007e\u0052\u0057\u0064\u006e\u0074\u0065\u0025\u0063\u006d\u0021\u0070\u0053\u0028\u0031\u006b\u007b\u0042\u0029\u0062\u0054\u004e\u0021\u0050\u0041\u0054\u0066\u004c\u0077\u0033\u003a\u0063\u0052\u0040\u003f\u0074\u005a\u0023\u0029\u0070\u0039\u0063\u003f\u003f\u0034\u007c\u007a\u0023\u002f\u002a\u0071\u0054\u007e\u0074\u006b\u006f\u0063\u007b\u0066\u0069\u0024\u0038\u004f\u002b\u0023\u005b\u0034\u0068\u006f\u006f\u0042\u007e\u0073\u0041\u004b\u0048\u0028\u0030\u0030\u0038\u0055\u003b\u0022\u006b\u004e\u003b\u0021\u003c\u005a\u0039\u005f\u0022\u0079\u0025\u004b\u003c\u0076\u0030\u0054\u0021\u0075\u0053\u0059\u0058\u0064\u0040\u0079\u007e\u0044\u0034\u0059\u004b\u0021\u0023\u0053\u0039\u0022\u0074\u006c\u0039\u0075\u0041\u0023\u005a\u0065\u0028\u0032\u0023\u004b\u002c\u0033\u0054\u0048\u0044\u0034\u0051\u002c\u003d\u0028\u006a\u0033\u004c\u0064\u0024\u0077\u0050\u0034\u007b\u005f\u0040\u0052\u003f\u0058\u0076\u003a\u0065\u0062\u0041\u0059\u003a\u0028\u005f\u0032\u007d\u006d\u0049\u0021\u007b\u0067\u007c\u0044\u0059\u003a\u007b\u005f\u0064\u0026\u007a\u0065\u006a\u007e\u002e\u0032\u0026\u005f\u004e\u0055\u0051\u0079\u0051\u0043\u007c\u0022\u004b\u005d\u0068\u0035\u0064\u006d\u0049\u0071\u0058\u0069\u0055\u003b\u0069\u002e\u0054\u0058\u0071\u0024\u003f\u007e\u002f\u0051\u006d\u0057\u0041\u007a\u0053\u0044\u0040\u0033\u005d\u0070\u0031\u0047\u0034\u0075\u0035\u0064\u006d\u0049\u0071\u0058\u0069\u006f\u0047\u002e\u0064\u004d\u002f\u0044\u0058\u002e\u007e\u003b\u007c\u006d\u0051\u006d\u0057\u0041\u007a\u0053\u003a\u0071\u0046\u0054\u0041\u0030\u003c\u0045\u0061\u007e\u0051\u0051\u0066\u003d\u003e\u006d\u004e\u007b\u0060\u006c\u0039\u0052\u007e\u007c\u003a\u0044\u0057\u0060\u0028\u005f\u003d\u0049\u0023\u002a\u006f\u0041\u0079\u005e\u0039\u004b\u006d\u0061\u0076\u0077\u0069\u002b\u0044\u004e\u0038\u0030\u0076\u0022\u005b\u0034\u0054\u002b\u003b\u0051\u0047\u0070\u0047\u002f\u0045\u002c\u0022\u0079\u0074\u0039\u0039\u0067\u006f\u0075\u0030\u0037\u005a\u004a\u007c\u0024\u0072\u0056\u0078\u007a\u0062\u0037\u0034\u0079\u0022\u0023\u0058\u003a\u007d\u005d\u0079\u006a\u0045\u0047\u007e\u0037\u0042\u0078\u0029\u0072\u0037\u004f\u0075\u005e\u006c\u002f\u0025\u0031\u003d\u002f\u0042\u002f\u0024\u0077\u0041\u0049\u0061\u004b\u0054\u0026\u005e\u0060\u0075\u0026\u0023\u0079\u0053\u002f\u0065\u004d\u0070\u0031\u0036\u0032\u007a\u004e\u0067\u0077\u007a\u0079\u0046\u0073\u0074\u0064\u0053\u002c\u0075\u0031\u0066\u0034\u0069\u0077\u0066\u003d\u0059\u003d\u0066\u003c\u002c\u007b\u007d\u0062\u0034\u0038\u003e\u006b\u005f\u0047\u007e\u0028\u005e\u0044\u0069\u007c\u0074\u0066\u002b\u0033\u0054\u003d\u0037\u002e\u003e\u0056\u0064\u006a\u0050\u007a\u0067\u0077\u0074\u0055\u0051\u0066\u0036\u003e\u0037\u0030\u0063\u0065\u002b\u005e\u0062\u0079\u002e\u0043\u003d\u0029\u002a\u0034\u0024\u0038\u0045\u005a\u0041\u0039\u0056\u0075\u006e\u0046\u0069\u007d\u002e\u003c\u0070\u0030\u003a\u0065\u0046\u0040\u007e\u0034\u0046\u0035\u0056\u0036\u004a\u007d\u0066\u007b\u006b\u0050\u0024\u0062\u0064\u0025\u0058\u004d\u002e\u006c\u0070\u0069\u0038\u0053\u0040\u0064\u0052\u0046\u0050\u0060\u0071\u0060\u0060\u002b\u005d\u0042\u007e\u005d\u002c\u0049\u003e\u0061\u0078\u005e\u0078\u0073\u0043\u005f\u0040\u007b\u0047\u004a\u0067\u0068\u006f\u0033\u007b\u004e\u0033\u004d\u0079\u0046\u0032\u0032\u0033\u005f\u006d\u0078\u0050\u0025\u0067\u0070\u0031\u0067\u0066\u0070\u0077\u0029\u0067\u003e\u0046\u005b\u0038\u0021\u0078\u006a\u004f\u0039\u005f\u0025\u0029\u0043\u0045\u0074\u0032\u0062\u0059\u007a\u0057\u0043\u004f\u0031\u005b\u0032\u0062\u002c\u007c\u006b\u0035\u005f\u0076\u006c\u0056\u002f\u0025\u0031\u006c\u0038\u0076\u003b\u006c\u004f\u004f\u006f\u0049\u0030\u004d\u0026\u0066\u0050\u0066\u006d\u0077\u0038\u0076\u003b\u006c\u004f\u004f\u0042\u006f\u0058\u0063\u0045\u0056\u007d\u002c\u0058\u0025\u007e\u003f\u0069\u0028\u003d\u0024\u006d\u0042\u0078\u0039\u004a\u0028\u006f\u004d\u005d\u0024\u0032\u004e\u0037\u0038\u006a\u002e\u006b\u0048\u0062\u0037\u0046\u002f\u0031\u004e\u005f\u0066\u005b\u0058\u0062\u0038\u006a\u0052\u0034\u0074\u006c\u002c\u007a\u0047\u003b\u0047\u0023\u004f\u005f\u002a\u003c\u006d\u0068\u0079\u0028\u0069\u006c\u005b\u003d\u0038\u002e\u0030\u0074\u0044\u0076\u002b\u0042\u003a\u0057\u007b\u003c\u0051\u004f\u0054\u0069\u0053\u0033\u0051\u007c\u0029\u0051\u0047\u004c\u002c\u0048\u007c\u0029\u0033\u0022\u0032\u0043\u0043\u0045\u004d\u007e\u0063\u005f\u0026\u0028\u0046\u0026\u002c\u0066\u0069\u0033\u0054\u004b\u005d\u0028\u005f\u0028\u0068\u0032\u0043\u0026\u007e\u0067\u0026\u003a\u0024\u0050\u0040\u006e\u004f\u0042\u002f\u0024\u0077\u0041\u0049\u0029\u005f\u002f\u0079\u0024\u0033\u0054\u0036\u005d\u0071\u0030\u004a\u0069\u0054\u003a\u0078\u0049\u0077\u0077\u0052\u002f\u003d\u0071\u004b\u004f\u004d\u005e\u005d\u0048\u003a\u006e\u002c\u0075\u003c\u0060\u003f\u0058\u004f\u002a\u0058\u0064\u0029\u003f\u003d\u0056\u0046\u004a\u0069\u0046\u0031\u0075\u0050\u0074\u0050\u004a\u0069\u0054\u003a\u0078\u0049\u006f\u005f\u006a\u0061\u007b\u0071\u0029\u0054\u0021\u0054\u007b\u004e\u0062\u0079\u004f\u0054\u005f\u0069\u0066\u0045\u0025\u0061\u004f\u007e\u0041\u0039\u0034\u003a\u0071\u0024\u0077\u006f\u002e\u0032\u0053\u0034\u0036\u0059\u0073\u0058\u0069\u0022\u0056\u007b\u004d\u0025\u005e\u0059\u005d\u007b\u005f\u0031\u002c\u002c\u0075\u0045\u0029\u004e\u0048\u0076\u0031\u004b\u004e\u0048\u0054\u0073\u0075\u0075\u0070\u0033\u005d\u0060\u006f\u004c\u004a\u0030\u002f\u0049\u002a\u0026\u0068\u007c\u0040\u006c\u0043\u0065\u0035\u007c\u0036\u0050\u0037\u006e\u002f\u0061\u0067\u0074\u0075\u002f\u005a\u0043\u0060\u0039\u002c\u004f\u007a\u0067\u003d\u0035\u0078\u005a\u0050\u007e\u006a\u007e\u0038\u0064\u0025\u0068\u005a\u002b\u003c\u005f\u007c\u0069\u0066\u004d\u002a\u005b\u0045\u0053\u0029\u0022\u003a\u0065\u0051\u007d\u0034\u002c\u005e\u0038\u004e\u0030\u0068\u0053\u0040\u006e\u0049\u0047\u0064\u006a\u0073\u0026\u0057\u0051\u0034\u005d\u0078\u0022\u0041\u002a\u0053\u005f\u005a\u003c\u002e\u0029\u0034\u0025\u004b\u004d\u0062\u0021\u0077\u0026\u0037\u006a\u0059\u0054\u0032\u0021\u004b\u0023\u0065\u003e\u005a\u0032\u0036\u005a\u0028\u0048\u0041\u0035\u0042\u0036\u0045\u002a\u0075\u004e\u006b\u0078\u002f\u004d\u0034\u002e\u0076\u0049\u007b\u0073\u005a\u003d\u0069\u0049\u0040\u0045\u0053\u006e\u0022\u0052\u0041\u006b\u004e\u003e\u0050\u0056\u0066\u0073\u006e\u004f\u0057\u0026\u0053\u0032\u0072\u0048\u006e\u0052\u0041\u0037\u0047\u0074\u002c\u0044\u0059\u0054\u0058\u0066\u003f\u002f\u0036\u0048\u006f\u0044\u002e\u0050\u003a\u0048\u0062\u0037\u007c\u0038\u0057\u006f\u003f\u0048\u0075\u0044\u0033\u006d\u0043\u0067\u003c\u0051\u0066\u003a\u005d\u0079\u0022\u0049\u0076\u0033\u004c\u0063\u0069\u0046\u006f\u003e\u0071\u005e\u002a\u0066\u003b\u0026\u0034\u0047\u006a\u0079\u004f\u007b\u0036\u005f\u0053\u0063\u005d\u0073\u0059\u0029\u006c\u0044\u0054\u006b\u002c\u0056\u004a\u0077\u004b\u005d\u004b\u0074\u007d\u007a\u0064\u006e\u0060\u0025\u0076\u0077\u0037\u0055\u0055\u0039\u007c\u005b\u0068\u0041\u0076\u0077\u0075\u003f\u0050\u007d\u0040\u0021\u0023\u006b\u0039\u002b\u006c\u002c\u003a\u007b\u0033\u0029\u0024\u006d\u003c\u002e\u007c\u0028\u0078\u005f\u0051\u0052\u0023\u0067\u0064\u0076\u005a\u003b\u004a\u0036\u0062\u0063\u0065\u0041\u002a\u0049\u0044\u0030\u007d\u007e\u0078\u0039\u0024\u0021\u0057\u0043\u0053\u0023\u0029\u0065\u006b\u0062\u005d\u0045\u0043\u0062\u0077\u0075\u003f\u0028\u0039\u0058\u0071\u0046\u004c\u002a\u0067\u0023\u0029\u0065\u006b\u0062\u005d\u0063\u002e\u0077\u0026\u004d\u0078\u0029\u0021\u0079\u0037\u0030\u006d\u005a\u0048\u007b\u0036\u003b\u006c\u006f\u004b\u0048\u0055\u0063\u006d\u003b\u003b\u0062\u0064\u0040\u0036\u003b\u0056\u006d\u0072\u0053\u007d\u0050\u0059\u0058\u0071\u006e\u0051\u006f\u0023\u004a\u002c\u0023\u005f\u004f\u0045\u0073\u0062\u0073\u0038\u0029\u0043\u0050\u004b\u004b\u0028\u0059\u002a\u0056\u007a\u005f\u0062\u003b\u004c\u0024\u0056\u0043\u006c\u006e\u0065\u004c\u007e\u006d\u007a\u0033\u0022\u002e\u005a\u004c\u0066\u0064\u002a\u002c\u003c\u0038\u0046\u0036\u006d\u004a\u006d\u0076\u003c\u0074\u0054\u0076\u0052\u0043\u0055\u0047\u006a\u0062\u0031\u004c\u0076\u005a\u0077\u003b\u0074\u0054\u0076\u002c\u0074\u005e\u0047\u0058\u005d\u0063\u0049\u004c\u0022\u007c\u0045\u0040\u007b\u002c\u002b\u0059\u005b\u003a\u0076\u0025\u0030\u0056\u0067\u002c\u0073\u006f\u0034\u0050\u0075\u0056\u0031\u002a\u0063\u007c\u007d\u0055\u0075\u007a\u0075\u0031\u006a\u0057\u0047\u0061\u0025\u0029\u002e\u0046\u0039\u007b\u007d\u0035\u0033\u0051\u004d\u0065\u0047\u0052\u0061\u0061\u0025\u0036\u0078\u0044\u0039\u003f\u006c\u0062\u0067\u0040\u006e\u0057\u0031\u002f\u006b\u0032\u0072\u006c\u0028\u0035\u004a\u005f\u005e\u0078\u002e\u0074\u0046\u0024\u0029\u0050\u007b\u0038\u0054\u0043\u004e\u0062\u0077\u0039\u0041\u004c\u0054\u0050\u007c\u0026\u0070\u0050\u0040\u004e\u0029\u0044\u0059\u002f\u002e\u003e\u0042\u0061\u0043\u0053\u0065\u0025\u0038\u006a\u0034\u002f\u0073\u006a\u0031\u006c\u0049\u0022\u0076\u002f\u0078\u0026\u005d\u0021\u0049\u0062\u0043\u007e\u0059\u0050\u0065\u0034\u002f\u0073\u006a\u0031\u006c\u0049\u0022\u0052\u0070\u005b\u006f\u006f\u0079\u0047\u0026\u0037\u005a\u0030\u0034\u0055\u0064\u0042\u0061\u0071\u0024\u0066\u0026\u005d\u0021\u0035\u0042\u0051\u0062\u003e\u0063\u004f\u0053\u006b\u0067\u0028\u007d\u006d\u0079\u0030\u0071\u004a\u0067\u0040\u0055\u003b\u005e\u0058\u0047\u0040\u0051\u007d\u005d\u0028\u0077\u0057\u0065\u0058\u0050\u0022\u0021\u0021\u007a\u006f\u006e\u0022\u005d\u0031\u0048\u0024\u0078\u004b\u003c\u0047\u0032\u0052\u0070\u0041